void printRowMajor(int** arr, int rows, int cols) {
    std::cout << "Row-major traversal:\n";
    for(int i = 0; i < rows; i++) {
        for(int j = 0; j < cols; j++) {
            std::cout << arr[i][j] << " ";
        }
        std::cout << std::endl;
    }
}

